import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_naive_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_naive_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    const int N,
    const int Cin,
    const int D,
    const int H,
    const int W,
    const int Cout,
    const int KD,
    const int KH,
    const int KW,
    const int stride,
    const int pad,
    const int out_pad, 
    const int D_out,
    const int H_out,
    const int W_out
){
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index >= N * Cout * D_out * H_out * W_out) {
        return;
    }

    // Decode the flattened index
    int w_out_idx = index % W_out;
    int h_out_idx = (index / W_out) % H_out;
    int d_out_idx = (index / (W_out * H_out)) % D_out;
    int c_out_idx = (index / (W_out * H_out * D_out)) % Cout;
    int n_idx = index / (W_out * H_out * D_out * Cout);

    float val = 0.0f;
    // Naive summation over kernel
    for(int c_in_idx = 0; c_in_idx < Cin; ++c_in_idx){
        for(int kd = 0; kd < KD; ++kd){
            int d_in_idx = (d_out_idx + pad - kd) / stride;
            if(((d_out_idx + pad - kd) % stride) != 0) continue;
            if(d_in_idx < 0 || d_in_idx >= D) continue;

            for(int kh = 0; kh < KH; ++kh){
                int h_in_idx = (h_out_idx + pad - kh) / stride;
                if(((h_out_idx + pad - kh) % stride) != 0) continue;
                if(h_in_idx < 0 || h_in_idx >= H) continue;

                for(int kw_ = 0; kw_ < KW; ++kw_){
                    int w_in_idx = (w_out_idx + pad - kw_) / stride;
                    if(((w_out_idx + pad - kw_) % stride) != 0) continue;
                    if(w_in_idx < 0 || w_in_idx >= W) continue;

                    float inp_val = input[n_idx * (Cin * D * H * W)
                                         + c_in_idx * (D * H * W)
                                         + d_in_idx * (H * W)
                                         + h_in_idx * W
                                         + w_in_idx];

                    float wgt_val = weight[c_in_idx * (Cout * KD * KH * KW)
                                          + c_out_idx * (KD * KH * KW)
                                          + kd * (KH * KW)
                                          + kh * KW
                                          + kw_];

                    val += inp_val * wgt_val;
                }
            }
        }
    }
    output[index] = val;
}

// C++/CUDA function that wraps kernel launch
torch::Tensor conv_transpose3d_naive_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int64_t stride,
    int64_t padding,
    int64_t output_padding
) {
    // input: (N, Cin, D, H, W)
    // weight: (Cin, Cout, KD, KH, KW)
    int N = input.size(0);
    int Cin = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    int KD = weight.size(2);
    int KH = weight.size(3);
    int KW = weight.size(4);
    int Cout = weight.size(1);

    // Compute output dimensions
    // Deconv dimension formula: (D_in - 1) * stride - 2*padding + KD + output_padding
    int D_out = (D - 1) * stride - 2*padding + KD + output_padding;
    int H_out = (H - 1) * stride - 2*padding + KH + output_padding;
    int W_out = (W - 1) * stride - 2*padding + KW + output_padding;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({N, Cout, D_out, H_out, W_out}, options);

    int total_threads = N * Cout * D_out * H_out * W_out;
    int blockSize = 256;
    int gridSize = (total_threads + blockSize - 1) / blockSize;

    conv_transpose3d_naive_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, Cin, D, H, W, Cout, KD, KH, KW,
        stride, padding, output_padding,
        D_out, H_out, W_out
    );
    return output;
}
"""

conv_transpose3d_naive_cpp_source = r"""
torch::Tensor conv_transpose3d_naive_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int64_t stride,
    int64_t padding,
    int64_t output_padding
);
"""

# Compile and load the inline extension
transposed_conv_naive = load_inline(
    name="transposed_conv_naive",
    cpp_sources=conv_transpose3d_naive_cpp_source,
    cuda_sources=conv_transpose3d_naive_source,
    functions=["conv_transpose3d_naive_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Custom transposed 3D convolution using a naive CUDA kernel.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding

        # Weight shape for ConvTranspose3d is (in_channels, out_channels, kD, kH, kW)
        # We'll store it as a learnable parameter
        w_shape = (in_channels, out_channels, kernel_size, kernel_size, kernel_size)
        self.weight = nn.Parameter(torch.randn(w_shape))
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.bias = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        out = transposed_conv_naive.conv_transpose3d_naive_cuda(
            x, 
            self.weight, 
            self.stride, 
            self.padding, 
            self.output_padding
        )
        if self.bias is not None:
            # Add bias as [1, out_channels, 1, 1, 1]
            out = out + self.bias.unsqueeze(0).unsqueeze(-1).unsqueeze(-1).unsqueeze(-1)
        return out
